<?php defined('ABSPATH') || exit;$base=home_url('/companion/');$root='dungeon-master/campaigns/'.$campaign->id().'/journal'; ?>
<section class="gmrc-campaign-journal"><header class="gmrc-campaign-journal__hero"><div><p class="gmrc-dm-desk__eyebrow"><?php echo esc_html($entry->categoryLabel()); ?> · <?php echo esc_html(ucfirst($entry->status())); ?><?php echo $entry->pinned()?' · ★ Pinned':''; ?></p><h1><?php echo esc_html($entry->title()); ?></h1><?php if($linkedSession): ?><p>Linked to Session <?php echo esc_html((string)$linkedSession->number()); ?> · <?php echo esc_html($linkedSession->title()); ?></p><?php else: ?><p>Campaign-wide private note</p><?php endif; ?></div><?php if(!$campaign->isArchived()): ?><a class="gmrc-journal-button" href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/'.$entry->id().'/edit',$base)); ?>">Edit Note</a><?php endif; ?></header>
<article class="gmrc-journal-page"><div class="gmrc-journal-page__content"><?php echo wpautop(esc_html($entry->content())); ?></div></article>
<?php if(!$campaign->isArchived()&&$entry->status()!=='archived'): ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="gmrc-journal-archive-form" onsubmit="return confirm('Archive this Journal entry?');"><input type="hidden" name="action" value="gmrc_app_request"><input type="hidden" name="gmrc_route" value="<?php echo esc_attr($root.'/'.$entry->id().'/archive'); ?>"><input type="hidden" name="_method" value="POST"><input type="hidden" name="gmrc_nonce" value="<?php echo esc_attr(wp_create_nonce('gmrc_dm_journal_'.$campaign->id())); ?>"><button type="submit">Archive page</button></form><?php endif; ?>
<p class="gmrc-journal-back"><a href="<?php echo esc_url(add_query_arg('gmrc_route',$root,$base)); ?>">← Back to Campaign Journal</a></p></section>
